 if ( ! defined( 'ABSPATH' ) ) { exit; } require_once __DIR__ . '/class-mixer-all.php'; class HVM_Widget_ConfSchedule extends HVM_Widget_Base { public function get_name() { return 'hvm_conf_schedule'; } public function get_title() { return 'Conference Timeline'; } public function get_icon() { return 'eicon-time-line'; } protected function register_controls() { $cm = '\Elementor\Controls_Manager'; $this->start_controls_section( 'ctl_style', array( 'label' => 'Cards', 'tab' => constant( "$cm::TAB_STYLE" ), ) ); $this->add_responsive_control( 'ctl_min_height', array( 'label' => 'Card min height', 'type' => constant( "$cm::SLIDER" ), 'size_units' => array( 'px', 'vh' ), 'range' => array( 'px' => array( 'min' => 120, 'max' => 500 ), 'vh' => array( 'min' => 10, 'max' => 80 ), ), 'default' => array( 'unit' => 'px', 'size' => 200 ), 'selectors' => array( '{{WRAPPER}} .hvm-ctl-card' => 'min-height:{{SIZE}}{{UNIT}};' ), ) ); $this->add_responsive_control( 'ctl_gap', array( 'label' => 'Gap between cards', 'type' => constant( "$cm::SLIDER" ), 'size_units' => array( 'px' ), 'range' => array( 'px' => array( 'min' => 0, 'max' => 60 ) ), 'default' => array( 'unit' => 'px', 'size' => 20 ), 'selectors' => array( '{{WRAPPER}} .hvm-ctl-list' => 'gap:{{SIZE}}{{UNIT}};' ), ) ); $this->add_control( 'ctl_overlay', array( 'label' => 'Overlay color', 'type' => constant( "$cm::COLOR" ), 'default' => 'rgba(7,7,37,0.9)', 'selectors' => array( '{{WRAPPER}} .hvm-ctl-card' => '--hvm-ctl-ov:{{VALUE}};' ), ) ); $this->add_responsive_control( 'ctl_img_pos', array( 'label' => 'Image position', 'type' => constant( "$cm::SELECT" ), 'default' => 'center center', 'options' => array( 'center center' => 'Center Center', 'center left' => 'Center Left', 'center right' => 'Center Right', 'center top' => 'Top Center', 'left top' => 'Top Left', 'right top' => 'Top Right', 'center bottom' => 'Bottom Center', 'left bottom' => 'Bottom Left', 'right bottom' => 'Bottom Right', ), 'selectors' => array( '{{WRAPPER}} .hvm-ctl-card' => 'background-position:{{VALUE}};' ), ) ); $this->add_control( 'ctl_title_color', array( 'label' => 'Title color', 'type' => constant( "$cm::COLOR" ), 'default' => '#FFFFFF', 'selectors' => array( '{{WRAPPER}} .hvm-ctl-title' => 'color:{{VALUE}};' ), ) ); $this->add_group_control( \Elementor\Group_Control_Typography::get_type(), array( 'name' => 'ctl_title_typo', 'label' => 'Title typography', 'selector' => '{{WRAPPER}} .hvm-ctl-title', ) ); $this->add_control( 'ctl_tags_color', array( 'label' => 'Tags color', 'type' => constant( "$cm::COLOR" ), 'default' => '#FFFFFF', 'selectors' => array( '{{WRAPPER}} .hvm-ctl-tag' => 'color:{{VALUE}};' ), ) ); $this->add_group_control( \Elementor\Group_Control_Typography::get_type(), array( 'name' => 'ctl_tags_typo', 'label' => 'Tags typography', 'selector' => '{{WRAPPER}} .hvm-ctl-tag', ) ); $this->add_control( 'ctl_desc_color', array( 'label' => 'Description color', 'type' => constant( "$cm::COLOR" ), 'default' => '#FFFFFF', 'selectors' => array( '{{WRAPPER}} .hvm-ctl-desc' => 'color:{{VALUE}};' ), ) ); $this->add_group_control( \Elementor\Group_Control_Typography::get_type(), array( 'name' => 'ctl_desc_typo', 'label' => 'Description typography', 'selector' => '{{WRAPPER}} .hvm-ctl-desc', ) ); $this->end_controls_section(); } protected function render() { $rows = hvm_rows( 'schedule' ); echo '<section id="hvm-conf-timeline" class=" hvm-conf-timeline">'; echo '<div class="hvm-boxed hvm-ctl-list">'; if ( ! $rows ) { $this->empty_hint( 'Timeline — add cards in this Conference\'s Timeline tab' ); } foreach ( $rows as $r ) { $img = ! empty( $r['image'] ) ? hvm_img_url( $r['image'], 'full' ) : ''; $style = $img ? ' style="background-image:url(\'' . esc_url( $img ) . '\')"' : ''; echo '<article class="hvm-ctl-card"' . $style . '>'; echo '<div class="hvm-ctl-body">'; if ( ! empty( $r['title'] ) ) { echo '<h3 class="hvm-ctl-title">' . esc_html( $r['title'] ) . '</h3>'; } if ( ! empty( $r['tags'] ) ) { $tags = array_filter( array_map( 'trim', explode( ',', $r['tags'] ) ) ); if ( $tags ) { echo '<div class="hvm-ctl-tags">'; foreach ( $tags as $t ) { echo '<span class="hvm-ctl-tag">' . esc_html( $t ) . '</span>'; } echo '</div>'; } } if ( ! empty( $r['short_desc'] ) ) { echo '<p class="hvm-ctl-desc">' . esc_html( $r['short_desc'] ) . '</p>'; } echo '</div></article>'; } echo '</div></section>'; } } add_filter( 'hvm_mixer_widget_classes', function ( $classes ) { $classes[] = 'HVM_Widget_ConfSchedule'; return $classes; } ); 